@decorator
def reraise(call, errors, into):
    """Decorator form: reraises errors as other exception or calls callback."""
    errors = _ensure_exceptable(errors)
    try:
        return call()
    except errors as e:
        if callable(into):
            raise into(e)
        else:
            raise_from(into, e)

